for (const Point2d& p : P1) {
    cgalP1.push_back(Point_2(p.x(), p.y()));
}
for (const Point2d& p : P2) {
    cgalP2.push_back(Point_2(p.x(), p.y()));
}

Pwh_list_2 result;
CGAL::intersection(cgalP1, cgalP2, std::back_inserter(result));

std::vector<PolygonWithHoles2d> output;
for (const Polygon_with_holes_2& pwh : result) {
    PolygonWithHoles2d poly;

    // Outer boundary
    const Polygon_2& outer = pwh.outer_boundary();
