        double x, y;
        std::stringstream ssx, ssy;
        ssx << std::setprecision(std::numeric_limits<double>::digits10+1) << it->x();
        ssx >> x;
        ssy << std::setprecision(std::numeric_limits<double>::digits10+1) << it->y();
        ssy >> y;
        poly.outer_boundary.emplace_back(x, y);
    }

    // Holes
    for (auto hit = pwh.holes_begin(); hit != pwh.holes_end(); ++hit) {
        std::vector<Point2d> hole;
        for (auto it = hit->vertices_begin(); it != hit->vertices_end(); ++it) {
            double x, y;
